 c.setFillColor(HexColor('#F8F6F1'));c.rect(0,0,595,842,fill=1,stroke=0);c.setFillColor(HexColor('#247D79'));c.setFont('Body',9);c.drawString(45,794,'CADENCELAB / MULTIMODAL AI HACKATHON / TRACK C');c.setFillColor(HexColor('#202422'));c.setFont('Display',26);c.drawString(45,740,title);c.setFont('Body',10);c.setFillColor(HexColor('#626760'));c.drawString(45,711,subtitle);c.setStrokeColor(HexColor('#B7482D'));c.line(45,692,550,692);c.setFont('Body',8);c.drawString(45,36,'Evidence, assumptions and limitations in one reproducible workbench');c.drawRightString(550,36,f'{n} / 6')
